import React, { useEffect, useState } from 'react';
import { Article } from './ArticleCard';

export default function Keywords({ articles }: { articles: Article[] }) {
    const [keywords, setKeywords] = useState<{ word: string, count: number }[]>([]);

    useEffect(() => {
        const extract = async () => {
            const text = articles.map(a => `${a.original_title} ${a.korean_title} ${a.summary}`).join(' ');

            const words = text
                .replace(/[^\w가-힣\s]/g, '')
                .split(/\s+/)
                .filter(w => w.length > 1);

            const stopWords = ['하는', '가장', '위해', '대한', '있는', '통해', '이러한', '어떻게', '수집', '기사', '뉴스', 'the', 'and', 'for', 'with', 'that', 'this', 'from', 'are', '그렇다면', '하지만', '그리고', '그들은', 'of', 'in', 'to', 'on', 'is', 'it'];

            const counts: Record<string, number> = {};
            words.forEach(w => {
                const word = w.toLowerCase();
                if (!stopWords.includes(word) && !/\d/.test(word)) {
                    counts[word] = (counts[word] || 0) + 1;
                }
            });

            const sorted = Object.entries(counts)
                .sort((a, b) => b[1] - a[1])
                .slice(0, 20)
                .map(([word, count]) => ({ word, count }));

            setKeywords(sorted);
        };

        extract();
    }, [articles]);

    if (keywords.length === 0) return null;

    return (
        <div className="mt-20 py-12 border-t border-dashed border-card-border animate-fade-in">
            <h3 className="text-center mb-8 text-text-main text-xl font-bold">
                🌟 이번 뉴스 요약 Top 20 핵심 키워드
            </h3>
            <div className="flex flex-wrap gap-3.5 justify-center px-4">
                {keywords.map((k, i) => (
                    <span
                        key={i}
                        className="px-5 py-2.5 rounded-full bg-white/5 text-text-main text-[0.95rem] font-medium shadow-[0_4px_15px_rgba(0,0,0,0.1)] border border-white/10 transition-all duration-300 hover:bg-accent hover:text-white hover:scale-105 hover:-translate-y-1 hover:border-accent hover:shadow-[0_8px_25px_var(--accent-glow)] inline-flex items-center justify-center text-center cursor-default shrink-0"
                    >
                        #{k.word} <span className="text-xs opacity-50 ml-1.5 font-bold">({k.count})</span>
                    </span>
                ))}
            </div>
        </div>
    );
}
